char arr[] = "Pointer Logic"; // Null-terminated array
char* ptr = arr;

// Traversal and Modification using pointers
while (*ptr != '\0') {
    if (*ptr == ' ') {
        *ptr = '-';
    }
    ptr++;
}

// Result: "Pointer-Logic"

